using System.Text.Json;
using System.Text.RegularExpressions;
using Agency.Huddle.App.Skills;

namespace Agency.Huddle.Tests.Skills;

/// <summary>
/// Pins the shipped built-in <c>SkillsCatalog.json</c>, the embedded resource generated by
/// <c>agents/scripts/Build-SkillsCatalog.ps1</c>.
/// </summary>
public sealed partial class SkillsCatalogFileTests
{
    private const string ResourceName = "Skills/SkillsCatalog.json";

    private static readonly string[] ExpectedKeys =
    [
        "id", "name", "description", "publisher", "repo", "path",
        "link", "commit", "license", "category", "subCategory", "requires",
    ];

    /// <summary>Matches a full 40-character lowercase hex commit id.</summary>
    [GeneratedRegex("^[0-9a-f]{40}$", RegexOptions.CultureInvariant)]
    private static partial Regex CommitPattern();

    /// <summary>Reads and parses the embedded catalog; an absent resource yields an empty list so assertions name the problem.</summary>
    private static List<JsonElement> LoadEntries()
    {
        using Stream? stream = typeof(SkillCatalog).Assembly.GetManifestResourceStream(ResourceName);
        if (stream is null)
        {
            return [];
        }

        using JsonDocument document = JsonDocument.Parse(stream);
        return [.. document.RootElement.EnumerateArray().Select(static element => element.Clone())];
    }

    /// <summary>The catalog is embedded in the app assembly, parses as an array and is not empty.</summary>
    [Fact]
    public void Catalog_IsEmbeddedAndParses()
    {
        Assert.NotEmpty(LoadEntries());
    }

    /// <summary>Every entry carries exactly the 12 documented keys.</summary>
    [Fact]
    public void Catalog_EveryEntryHasTheTwelveKeys()
    {
        List<JsonElement> entries = LoadEntries();

        Assert.NotEmpty(entries);
        foreach (JsonElement entry in entries)
        {
            string[] keys = [.. entry.EnumerateObject().Select(static property => property.Name).Order(StringComparer.Ordinal)];
            Assert.Equal(ExpectedKeys.Order(StringComparer.Ordinal), keys);
        }
    }

    /// <summary>Ids are unique across the catalog.</summary>
    [Fact]
    public void Catalog_IdsAreUnique()
    {
        List<JsonElement> entries = LoadEntries();
        List<string?> ids = [.. entries.Select(static entry => entry.GetProperty("id").GetString())];

        Assert.NotEmpty(ids);
        Assert.Equal(ids.Count, ids.Distinct(StringComparer.Ordinal).Count());
    }

    /// <summary>Fixture rows are left out of the shipped catalog.</summary>
    [Fact]
    public void Catalog_HasNoFixtureCategory()
    {
        List<JsonElement> entries = LoadEntries();

        Assert.NotEmpty(entries);
        Assert.DoesNotContain(entries, static entry => string.Equals(entry.GetProperty("category").GetString(), "Fixtures & Non-Skills", StringComparison.Ordinal));
    }

    /// <summary>Every commit is a full 40-character hex id.</summary>
    [Fact]
    public void Catalog_CommitsAreFortyHexCharacters()
    {
        List<JsonElement> entries = LoadEntries();

        Assert.NotEmpty(entries);
        Assert.All(entries, static entry => Assert.Matches(CommitPattern(), entry.GetProperty("commit").GetString() ?? string.Empty));
    }

    /// <summary>The catalog carries metadata only: no description is long enough to be skill body text.</summary>
    [Fact]
    public void Catalog_DescriptionsStayUnderTwelveHundredCharacters()
    {
        List<JsonElement> entries = LoadEntries();

        Assert.NotEmpty(entries);
        Assert.All(entries, static entry => Assert.InRange((entry.GetProperty("description").GetString() ?? string.Empty).Length, 1, 1200));
    }
}
